#!/usr/bin/env python3
"""Write the errno name table system:errno-value uses.

The names are those CPython's Modules/errnomodule.c can define, so on every
platform the engine knows exactly the names Python's errno module has there:
each row is compiled only where the platform defines that macro, as in
CPython. Give the errnomodule.c of the CPython release to match.
"""
import argparse
import re
from pathlib import Path


def render(names, release):
    lines = [
        "/* Generated by tools/generate_errno_names.py from CPython %s's" % release,
        " * Modules/errnomodule.c. Do not edit. Each row exists where the platform",
        " * defines the macro, as in Python's errno module. */",
        "#ifndef CETTA_ERRNO_NAMES_H",
        "#define CETTA_ERRNO_NAMES_H",
        "",
        "#include <errno.h>",
        "",
        "typedef struct { const char *name; int value; } CettaErrnoName;",
        "",
        "static const CettaErrnoName cetta_errno_names[] = {",
    ]
    for name in names:
        lines += ["#ifdef %s" % name, '    {"%s", %s},' % (name, name), "#endif"]
    lines += ["    {0, 0}", "};", "", "#endif", ""]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("errnomodule", type=Path)
    parser.add_argument("--release", required=True)
    parser.add_argument("--output", type=Path, default=Path("src/errno_names.h"))
    args = parser.parse_args()
    source = args.errnomodule.read_text()
    names = sorted(set(re.findall(r'add_errcode\("(E[A-Z0-9_]*)",\s*\1,', source)))
    if not names:
        raise SystemExit("no errno names found in %s" % args.errnomodule)
    args.output.write_text(render(names, args.release))
    print("%d errno names written to %s" % (len(names), args.output))


if __name__ == "__main__":
    main()
